function formatEditorValue(value: unknown) {
  if (typeof value === 'string') {
    const text = value.trim();
    if (!text) return '';

    try {
      return JSON.stringify(JSON.parse(text), null, 2);
    } catch {
      return value;
    }
  }

  if (value === undefined) return '';

  try {
