  } catch {
    return String(value ?? '');
  }
}

function formatPreviewValue(value: unknown) {
  if (typeof value === 'string') {
    const text = value.trim();
    if (!text) return '';

    try {
      return JSON.stringify(JSON.parse(text));
    } catch {
      return text.replace(/\s+/g, ' ');
