    return {
      width: fallbackWidth,
      props: {
        ...baseProps,
        position: {
          top: '4vh',
          left: SCRIPT_DIALOG_VIEWPORT_MARGIN,
        },
      },
    };
  }

  const dialogWidth = Math.min(requestedDialogWidth, availableWidth);
  const left = SCRIPT_DIALOG_VIEWPORT_MARGIN +
    Math.max(0, (availableWidth - dialogWidth) / 2);

  return {
    width: dialogWidth,
    props: {
      ...baseProps,
      position: {
        top: '4vh',
        left: Math.round(left),
