    automaticLayout: true,
    minimap: { enabled: false },
    scrollBeyondLastLine: false,
    wordWrap: 'on',
    fontFamily: 'Consolas, "SFMono-Regular", "Liberation Mono", monospace',
    fontSize: 13,
    lineHeight: 20,
    tabSize: 2,
