async function openEditorDialog() {
  if (isDisabled.value || editorOpen.value) return;
  editorOpen.value = true;
  const dialogLayout = resolveEditorDialogLayout();

  const schema: LowCodeFormSchema = {
    columns: 1,
    fields: [createDialogEditorField()],
    actions: [],
