    'stripe',
    'border',
    'round',
    'showHeader',
    'showFooter',
    'showOverflow',
    'showHeaderOverflow',
    'showFooterOverflow',
    'height',
    'minHeight',
    'maxHeight',
    'rowHeight',
    'headerHeight',
    'headerRowHeight',
    'footerHeight',
    'footerRowHeight',
    'cellConfig',
    'headerCellConfig',
    'footerCellConfig',
    'rowConfig',
    'rowDragConfig',
    'columnConfig',
    'sortConfig',
