<script setup lang="ts">
import { computed, inject } from 'vue';
import { VxeUI } from 'vxe-pc-ui';
import type { VxeButtonProps } from 'vxe-pc-ui';
import type {
  LowCodeButtonGroupAction,
  LowCodePageButtonGroupBlock,
  LowCodeRuntimeDirective,
